import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        // index floor*26+letter keeps lexicographic room order
        int[] cnt = new int[260];
        for (int i = 0; i < n; i++) {
            String op = st.nextToken();
            if (op.charAt(0) == '+') cnt[(op.charAt(1) - '0') * 26 + (op.charAt(2) - 'A')]++;
        }
        int best = 0;
        for (int r = 1; r < 260; r++) if (cnt[r] > cnt[best]) best = r;
        System.out.println("" + (char) ('0' + best / 26) + (char) ('A' + best % 26));
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	// index floor*26+letter keeps lexicographic room order
	cnt := make([]int, 260)
	for i := 0; i < n; i++ {
		sc.Scan()
		op := sc.Text()
		if op[0] == '+' {
			cnt[int(op[1]-'0')*26+int(op[2]-'A')]++
		}
	}
	best := 0
	for r := 1; r < 260; r++ {
		if cnt[r] > cnt[best] {
			best = r
		}
	}
	fmt.Printf("%c%c\n", '0'+best/26, 'A'+best%26)
}
